insert into plataformas (slug,nombre,estado,etiqueta_descarte,motivo_descarte,verificada_el) values ('domoblock','Domoblock','descartada','Sin supervisión','La propia plataforma declara que no está supervisada por la CNMV, que no es una Empresa de Servicios de Inversión y que sus productos no son valores negociables. Antes sus emisiones pasaban por una ESI autorizada; dejó de ser así a partir del proyecto DOMO-VLC-4.','2026-08-06');
