insert into plataformas (slug,nombre,estado,etiqueta_descarte,motivo_descarte,verificada_el) values ('goldfinch','Goldfinch','descartada','Cierre aprobado','En junio de 2026 la comunidad aprobó el cierre de Goldfinch Prime. Quedan más de 50 M$ sin devolver en los fondos de prestatarios y solo se ha recuperado en torno al 30 % del capital: de ocho prestatarios, dos en impago y seis en reestructuración.','2026-08-06');
