insert into plataformas (slug,nombre,estado,etiqueta_descarte,motivo_descarte,verificada_el) values ('realt','RealT','descartada','En liquidación','Detroit la demandó junto a sus 165 sociedades por más de 400 viviendas con infracciones, en la mayor demanda por insalubridad de la historia de la ciudad. Un juez le prohibió cobrar alquileres en las no conformes y le ordenó reparar. En julio de 2026 la propia empresa anunció liquidación voluntaria y la venta de sus más de 700 inmuebles en Detroit.','2026-08-06');
insert into fuentes (plataforma_id,url,titulo,consultada_el) values ((select id from plataformas where slug='realt'),'https://detroitmi.gov/news/city-scores-major-win-tenants-living-troubled-real-token-properties-are-subject-sweeping-lawsuit','Ciudad de Detroit · la ciudad gana una medida para los inquilinos de Real Token','2026-08-06');
insert into fuentes (plataforma_id,url,titulo,consultada_el) values ((select id from plataformas where slug='realt'),'https://www.bridgedetroit.com/detroit-sues-blockchain-real-estate-firm/','BridgeDetroit · Detroit demanda a Real Token por cientos de infracciones','2026-08-06');
