insert into fuentes (plataforma_id,url,titulo,consultada_el) values ((select id from plataformas where slug='toucan-protocol'),'https://carboncredits.com/verra-suspension-carbon-credits-proposes-immobilizing-credits/','CarbonCredits · Verra prohíbe tokenizar créditos retirados y propone inmovilizarlos','2026-08-06');
